 wrong:[
  {stmts:["Unity of command means one employee, one superior.","Unity of direction means one head and one plan.","Unity of direction prevents dual subordination.","Unity of command applies to each individual employee."], a:2, c:"uod", why:"Dual subordination is prevented by <b>unity of command</b>, not unity of direction."},
  {stmts:["Time study fixes standard time.","Motion study fixes rest intervals.","Method study finds the best way of doing a job.","Fatigue study helps decide rest intervals."], a:1, c:"mos", why:"Motion study removes unnecessary movements. Rest intervals come from <b>fatigue study</b>."},
  {stmts:["Fayol's principles came from personal experience.","Taylor's principles came from experimentation.","Fayol was a staunch supporter of unity of command.","Taylor's focus was improving overall administration."], a:3, c:"fvt", why:"Taylor's focus was <b>increasing productivity</b>; improving overall administration was Fayol's focus."},
  {stmts:["Route clerk is under the planning in-charge.","Inspector is under the production in-charge.","Speed boss is under the planning in-charge.","Disciplinarian is under the planning in-charge."], a:2, c:"ff", why:"Speed boss is under the <b>production</b> in-charge."},
  {stmts:["Principles of management are flexible.","Principles of management are rigid like laws of science.","Principles of management are contingent.","Principles of management are mainly behavioural."], a:1, c:"nature", why:"They are <b>not</b> rigid; they deal with human behaviour, so they are flexible."},
  {stmts:["A gang plank is used in emergencies.","A gang plank connects employees at the same level.","A gang plank removes the need to inform superiors.","A gang plank is a part of the scalar chain."], a:2, c:"scalar", why:"Superiors must still be <b>informed</b>; the gang plank only avoids delay."}
 ],
 para:[
  {target:"Unity of direction", c:"uod", sents:["Orbis Electronics makes phones and televisions.","Its engineers are trained every quarter on new chips.","The phone business and the TV business each have a separate head, a separate plan and a separate budget.","Salaries are reviewed once a year."], a:2, why:"Separate head and plan for each group of activities with the same objective is <b>unity of direction</b>."},
  {target:"Stability of personnel", c:"stab", sents:["Greenleaf Hotels hires chefs after a cooking test.","Chefs are kept in the same kitchen for at least three years so they can master the menu.","The kitchen is cleaned twice a day.","Every chef wears a name badge."], a:1, why:"A minimum fixed tenure to settle and perform is <b>stability of personnel</b>."},
  {target:"Fatigue study", c:"fs", sents:["Delivery riders at Zoomkart cover 60 km a day.","The company studied when riders made the most errors.","It then fixed a 20-minute rest after every three hours of riding.","Riders also get rain gear."], a:2, why:"Fixing the amount and frequency of rest is the result of <b>fatigue study</b>."},
  {target:"Equity", c:"equity", sents:["Sunbeam Textiles employs workers from five states.","All workers get the same leave and the same overtime rate, whatever their language or religion.","The factory runs two shifts.","New machines arrived last month."], a:1, why:"Same treatment regardless of language or religion is <b>equity</b>."}
 ],
 explain:[
  {s:"At a pharma plant, a worker gets orders from the shift in-charge and the safety officer at the same time, and they often conflict.", o:["Unity of direction","Unity of command","Discipline","Order"], a:1, c:"uoc", why:"The clue is <i>orders from the shift in-charge and the safety officer</i>: two superiors for one worker, so <b>unity of command</b> is violated."},
  {s:"A biscuit company tested five baking methods and adopted the one with the least waste across all its plants.", o:["Science, not rule of thumb","Harmony, not discord","Division of work","Order"], a:0, c:"sci", why:"The clue is <i>tested five methods… adopted the one</i>: scientific experiment replaces guesswork, so <b>science, not rule of thumb</b>."},
  {s:"A workshop pays a higher rate per piece to workers who meet the standard and a lower rate to those who don't.", o:["Remuneration of employees","Differential piece wage system","Equity","Initiative"], a:1, c:"dpw", why:"The clue is <i>higher rate… lower rate</i> linked to a <i>standard</i>: <b>differential piece wage system</b>."},
  {s:"A manager tells her team they will all share the credit and bonus for a client win.", o:["Esprit de corps","Equity","Remuneration","Order"], a:0, c:"esp", why:"The clue is <i>all share the credit</i>: team spirit, 'we' not 'I', so <b>esprit de corps</b>."},
  {s:"A company's managers consult worker representatives before buying new machines and reward ideas that cut costs.", o:["Initiative","Cooperation, not individualism","Harmony, not discord","Development of each person"], a:1, c:"coop", why:"The clue is <i>consult worker representatives</i> and <i>reward ideas</i>: <b>cooperation, not individualism</b>."},
  {s:"A toy firm decides that every wheel it makes will be one of three fixed sizes, so it fits all its cars.", o:["Simplification","Standardisation","Method study","Order"], a:1, c:"std", why:"The clue is <i>fixed sizes… fits all</i>: interchangeability through <b>standardisation</b>."}
 ]
